{
  "name": "opencode-model-status",
  "version": "1.0.0",
  "description": "OpenCode TUI plugin that shows the live status and 7-day history of an OpenCode Go model in the sidebar, powered by status.opencode.ai.",
  "type": "module",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "files": [
    "index.ts",
    "tui.tsx",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui",
    "status",
    "statuspage",
    "deepseek",
    "deepseek-v4",
    "opencode-go"
  ],
  "author": "Cristian Cibrian (https://github.com/cristiancibrian)",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cristiancibrian/opencode-model-status.git"
  },
  "homepage": "https://github.com/cristiancibrian/opencode-model-status#readme",
  "bugs": {
    "url": "https://github.com/cristiancibrian/opencode-model-status/issues"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  }
}
